# -*- coding: utf-8 -*-
"""高中地理必修、选择性必修相关内容要求的公开转述。

依据《普通高中地理课程标准（2017年版2020年修订）》必修课程与选择性必修课程的「内容要求」范围，
用自己的话转述，不是逐字原文，不核对页码，编号 B1/B2/S1/S2/S3 是本图谱自编。
B1、B2 对应必修第一、二册，S1、S2、S3 对应选择性必修第一、二、三册。
转述按教材章节的主题组织，只写课标主题范围内的要求，不加课标没有的要求；措辞可能与课标原文有出入。
2026-11-21 已对照课标 PDF 逐条核对：页码与核对结论见文末 CHECK，text 已按核对结果修正，以下措辞与 data 现行值一致。
"""
from __future__ import annotations

from geo_hs_lib import S, clause

_N = "自然地理基础"
_H = "人文地理基础"
_R = "区域发展"
_E = "资源环境与国家安全"

# 必修一：自然地理基础
clause("B1.01", _N, "宇宙中的地球", "运用资料说明地球所处的宇宙环境，以及太阳辐射和太阳活动对地球的影响。")
clause("B1.02", _N, "地球的演化与圈层结构", "运用地质年代表等资料简述地球的演化过程，并用示意图说明地球内部与外部圈层的划分及各圈层的主要特点。")
clause("B1.03", _N, "大气的组成与运动", "运用图表等资料，说明大气的组成和垂直分层，及其与生产和生活的联系。运用示意图等，说明大气受热过程与热力环流原理，并解释相关现象。")
clause("B1.04", _N, "水循环与海水", "用示意图说明水循环的过程及其地理意义，说出海水的性质及其运动形式对人类活动的影响。")
clause("B1.05", _N, "地貌", "通过野外观察或运用视频、图像，识别3~4种地貌，描述其景观的主要特点。")
clause("B1.06", _N, "植被与土壤", "通过野外观察或运用土壤标本，说明土壤的主要形成因素。通过野外观察或运用视频、图像，识别主要植被，说明其与自然环境的关系。")
clause("B1.07", _N, "自然灾害与防灾减灾", "运用资料，说明常见自然灾害的成因，了解避灾、防灾的措施。通过探究有关自然地理问题，了解地理信息技术的应用。")

# 必修二：人文地理基础
clause("B2.01", _H, "人口", "运用资料，描述人口分布、迁移的特点及其影响因素，并结合实例，解释区域资源环境承载力、人口合理容量。")
clause("B2.02", _H, "乡村和城镇的空间结构", "结合实例，解释城镇和乡村内部的空间结构，说明合理利用城乡空间的意义。")
clause("B2.03", _H, "城镇化与地域文化", "结合实例，说明地域文化在城乡景观上的体现。运用资料，说明不同地区城镇化的过程和特点，以及城镇化的利弊。")
clause("B2.04", _H, "产业区位因素", "结合实例分析农业、工业和服务业的区位因素及其变化。")
clause("B2.05", _H, "交通运输布局与区域发展", "结合实例说明区域发展对交通运输布局的影响，以及交通运输布局对区域发展的影响。")
clause("B2.06", _H, "环境与发展", "以国家某项重大发展战略为例，运用不同类型的专题地图，说明其地理背景。运用资料，归纳人类面临的主要环境问题，说明协调人地关系和可持续发展的主要途径及其缘由。")

# 选择性必修1：自然地理基础
clause("S1.01", _N, "地球的自转与公转", "运用示意图和资料说明地球自转和公转的特征。")
clause("S1.02", _N, "地球运动的地理意义", "说明地球运动产生的昼夜交替、时差、水平运动物体方向偏转、昼夜长短和正午太阳高度的变化与四季更替。")
clause("S1.03", _N, "地表形态的塑造", "结合实例，解释内力和外力对地表形态变化的影响，并说明人类活动与地表形态的关系。")
clause("S1.04", _N, "天气系统", "运用天气图等资料，说明锋面系统、气旋和反气旋等常见天气系统的特点及对天气的影响。")
clause("S1.05", _N, "气压带、风带与气候", "运用示意图，说明气压带、风带的分布，并分析气压带、风带对气候形成的作用，以及气候对自然地理景观形成的影响。")
clause("S1.06", _N, "水的运动", "绘制示意图，解释各类陆地水体之间的相互关系。运用世界洋流分布图，说明世界洋流的分布规律，并举例说明洋流对地理环境和人类活动的影响。运用图表，分析海—气相互作用对全球水热平衡的影响，解释厄尔尼诺、拉尼娜现象对全球气候和人类活动的影响。")
clause("S1.07", _N, "自然环境的整体性与差异性", "结合实例说明自然环境各要素间的相互作用，以及自然环境的地域分异规律。")

# 选择性必修2：区域发展
clause("S2.01", _R, "区域与区域发展", "结合实例，说明区域的含义及类型。")
clause("S2.02", _R, "自然环境与区域发展", "结合实例说明自然环境和自然资源对区域发展的影响。")
clause("S2.03", _R, "生态脆弱区与资源枯竭型城市", "以典型区域为例，分析生态脆弱区的综合治理和资源枯竭型城市的转型发展。")
clause("S2.04", _R, "城市与区域产业结构", "以某大都市为例，从区域空间组织的视角出发，说明大都市辐射功能。以某地区为例，分析地区产业结构变化过程及原因。")
clause("S2.05", _R, "区际联系与区域协调", "结合实例说明流域协调发展、资源跨区域调配、产业转移和国际合作等区际联系，及其对区域协调发展的意义。")

# 选择性必修3：资源、环境与国家安全
clause("S3.01", _E, "自然环境与人类社会", "说明自然环境的服务功能、自然资源的类型与特点，以及环境问题及其危害。")
clause("S3.02", _E, "资源安全与国家安全", "结合实例说明耕地、能源和海洋空间等资源与国家安全的关系，以及保障资源安全的途径。")
clause("S3.03", _E, "环境安全与国家安全", "结合实例说明环境污染、生态破坏和全球气候变化对国家安全的影响，以及环境治理与生态保护的措施。")
clause("S3.04", _E, "资源环境战略与行动", "了解走向生态文明、国家资源环境战略与政策，以及国际合作和公民可采取的行动。")

